import{_ as e,c as o,o as i,af as a}from"./chunks/framework.J4isc1KJ.js";const b=JSON.parse('{"title":"Table 组件设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"components/table-design.md","filePath":"components/table-design.md"}'),d={name:"components/table-design.md"};function c(t,l,r,n,s,h){return i(),o("div",null,l[0]||(l[0]=[a('<h1 id="table-组件设计说明" tabindex="-1">Table 组件设计说明 <a class="header-anchor" href="#table-组件设计说明" aria-label="Permalink to &quot;Table 组件设计说明&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><ol><li>在 <code>lit + unocss</code> 的基础上，提供可扩展的通用 Table。</li><li>支持滚动触发加载更多（Infinite Scroll）。</li><li>支持万级数据渲染优化（Virtual Scroll）。</li><li>保持常规能力可用：排序、分页、斑马纹、悬停、对齐、省略、行点击等。</li><li>支持合并单元格（<code>spanMethod</code>）。</li></ol><h2 id="总体架构" tabindex="-1">总体架构 <a class="header-anchor" href="#总体架构" aria-label="Permalink to &quot;总体架构&quot;">​</a></h2><p><code>se-table</code> 组件采用“数据处理层 + 渲染层”分离：</p><ol><li>数据处理层：</li></ol><ul><li>接收 <code>data / columns</code>。</li><li>维护 <code>sortedColumns / sortedData</code>。</li><li>根据模式组合出 <code>sourceData</code>（分页模式下为页切片，非分页下为全量已加载数据）。</li></ul><ol start="2"><li>渲染层：</li></ol><ul><li>普通模式：渲染全部 <code>sourceData</code>。</li><li>虚拟模式：仅渲染窗口内行，并插入上下占位行（spacer）。</li><li>合并模式：根据 <code>spanMethod</code> 计算 <code>rowspan/colspan</code>，并自动跳过被覆盖单元格。</li><li>滚动容器统一监听 <code>scroll</code>，同时驱动虚拟窗口和加载更多触发。</li></ul><h2 id="核心数据流" tabindex="-1">核心数据流 <a class="header-anchor" href="#核心数据流" aria-label="Permalink to &quot;核心数据流&quot;">​</a></h2><ol><li><code>data/columns</code> 变化：</li></ol><ul><li>重建 <code>sortedColumns</code>（清空 sortDirection）。</li><li>重建 <code>sortedData</code>。</li><li>重置分页到第 1 页。</li></ul><ol start="2"><li>点击表头排序：</li></ol><ul><li>方向在 <code>asc -&gt; desc -&gt; &#39;&#39;</code> 之间循环。</li><li><code>&#39;&#39;</code> 回退到原始 <code>data</code> 顺序。</li><li>派发 <code>sort-change</code> 事件。</li></ul><ol start="3"><li>分页变化：</li></ol><ul><li>更新 <code>currentPage</code>。</li><li>重置滚动位置。</li><li>派发 <code>page-change</code>。</li></ul><h2 id="infinite-scroll-设计" tabindex="-1">Infinite Scroll 设计 <a class="header-anchor" href="#infinite-scroll-设计" aria-label="Permalink to &quot;Infinite Scroll 设计&quot;">​</a></h2><h3 id="触发条件" tabindex="-1">触发条件 <a class="header-anchor" href="#触发条件" aria-label="Permalink to &quot;触发条件&quot;">​</a></h3><p>滚动容器触发 <code>scroll</code> 时，满足以下条件才派发 <code>load-more</code>：</p><ol><li><code>infiniteScroll = true</code></li><li><code>hasMore = true</code></li><li><code>loadingMore = false</code></li><li>未处于本轮触发锁（<code>loadMorePending = false</code>）</li><li>距离底部 <code>&lt;= loadMoreOffset</code></li></ol><h3 id="防抖-防重" tabindex="-1">防抖/防重 <a class="header-anchor" href="#防抖-防重" aria-label="Permalink to &quot;防抖/防重&quot;">​</a></h3><ol><li>一次触发后 <code>loadMorePending = true</code>，防止连续触发。</li><li>外部请求完成并将 <code>loadingMore</code> 设置回 <code>false</code> 后，解除锁，允许下一次触发。</li></ol><h3 id="外部协作约定" tabindex="-1">外部协作约定 <a class="header-anchor" href="#外部协作约定" aria-label="Permalink to &quot;外部协作约定&quot;">​</a></h3><p>父层需要负责：</p><ol><li>接收 <code>load-more</code> 事件。</li><li>设置 <code>loadingMore</code>。</li><li>追加数据到 <code>table.data</code>。</li><li>正确维护 <code>hasMore</code>。</li></ol><h2 id="virtual-scroll-设计" tabindex="-1">Virtual Scroll 设计 <a class="header-anchor" href="#virtual-scroll-设计" aria-label="Permalink to &quot;Virtual Scroll 设计&quot;">​</a></h2><h3 id="启用策略" tabindex="-1">启用策略 <a class="header-anchor" href="#启用策略" aria-label="Permalink to &quot;启用策略&quot;">​</a></h3><p>满足任一条件启用虚拟滚动：</p><ol><li><code>virtualScroll = true</code></li><li><code>sourceData.length &gt;= virtualThreshold</code></li></ol><h3 id="窗口计算" tabindex="-1">窗口计算 <a class="header-anchor" href="#窗口计算" aria-label="Permalink to &quot;窗口计算&quot;">​</a></h3><p>参数：</p><ol><li><code>scrollTop</code></li><li><code>viewportHeight</code></li><li><code>virtualRowHeight</code></li><li><code>virtualBuffer</code></li></ol><p>计算：</p><ol><li><code>start = floor(scrollTop / rowHeight) - buffer</code></li><li><code>visibleCount = ceil(viewportHeight / rowHeight) + buffer * 2</code></li><li><code>end = start + visibleCount</code></li><li>真实渲染行为 <code>sourceData[start, end)</code></li><li>上下占位高度：</li></ol><ul><li><code>topPadding = start * rowHeight</code></li><li><code>bottomPadding = (total - end) * rowHeight</code></li></ul><h3 id="性能收益" tabindex="-1">性能收益 <a class="header-anchor" href="#性能收益" aria-label="Permalink to &quot;性能收益&quot;">​</a></h3><p>万级数据下，DOM 行节点维持在“可视区 + buffer”规模，避免一次性挂载 10000+ 行导致的主线程卡顿。</p><h2 id="常规能力增强" tabindex="-1">常规能力增强 <a class="header-anchor" href="#常规能力增强" aria-label="Permalink to &quot;常规能力增强&quot;">​</a></h2><ol><li>列能力：</li></ol><ul><li><code>align</code>：左/中/右对齐。</li><li><code>ellipsis</code>：单行省略。</li><li><code>formatter</code>：格式化渲染。</li></ul><ol start="2"><li>交互能力：</li></ol><ul><li><code>row-click</code> 事件。</li><li><code>stickyHeader</code> 吸顶表头（滚动模式下）。</li></ul><ol start="3"><li>分页能力：</li></ol><ul><li><code>pagination</code> 开关。</li><li>输入页码 + 上一页/下一页按钮。</li></ul><ol start="4"><li>合并单元格能力：</li></ol><ul><li><code>spanMethod(args)</code> 支持返回 <code>[rowspan, colspan]</code> 或 <code>{ rowspan, colspan }</code>。</li><li>返回 <code>[0, 0]</code> / <code>{ rowspan: 0, colspan: 0 }</code> 表示该单元格被覆盖，不渲染。</li></ul><h2 id="与-native-ui-table-对齐建议-下一步" tabindex="-1">与 Native UI Table 对齐建议（下一步） <a class="header-anchor" href="#与-native-ui-table-对齐建议-下一步" aria-label="Permalink to &quot;与 Native UI Table 对齐建议（下一步）&quot;">​</a></h2><ol><li>增加 <code>rowSelection</code>（多选、全选、受控 keys）。</li><li>增加 <code>column.fixed</code>（左右固定列）。</li><li>增加 <code>expandable</code>（可展开行）。</li><li>增加 <code>remote</code> 模式（排序/分页/筛选由服务端驱动）。</li><li>增加 <code>summary</code> 与 <code>empty</code> slot。</li></ol><h2 id="风险与边界" tabindex="-1">风险与边界 <a class="header-anchor" href="#风险与边界" aria-label="Permalink to &quot;风险与边界&quot;">​</a></h2><ol><li>虚拟滚动默认假设固定行高（<code>virtualRowHeight</code>），若未来要支持动态行高，需要引入高度缓存与回流校正。</li><li><code>formatter</code> 当前为函数，建议只在 JS 场景配置，不建议通过 HTML attribute 透传。</li><li>无限滚动与分页同时开启时，组件会自动关闭分页逻辑（由 <code>infiniteScroll</code> 优先）。</li><li><code>spanMethod</code> 与虚拟滚动同时使用时，组件会优先保证正确性，自动退化为非虚拟渲染。</li></ol>',50)]))}const p=e(d,[["render",c]]);export{b as __pageData,p as default};
